108→		Timestamp:                time.Now().UTC().Format(time.RFC3339),
109→		UntrackedFiles:           untrackedFiles,
110→		UserPrompt:               userPrompt,
111→		LastTranscriptIdentifier: transcriptPos.LastUUID,
112→		StepTranscriptStart:      transcriptPos.LineCount,
113→	}
114→
115→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
116→	if err != nil {
117→		return fmt.Errorf("failed to marshal state: %w", err)
118→	}
119→
120→	if err := os.WriteFile(stateFile, data, 0o600); err != nil {
121→		return fmt.Errorf("failed to write state file: %w", err)
