123→
124→	fmt.Fprintf(os.Stderr, "Captured state before prompt: %d untracked files, transcript at line %d (uuid: %s)\n",
125→		len(untrackedFiles), transcriptPos.LineCount, transcriptPos.LastUUID)
126→	return nil
127→}
