	// Provides: user prompt (for commit message), untracked files (for new file detection),
	// and transcript position (for session state update).
	preState, err := LoadPrePromptState(sessionID)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to load pre-prompt state: %v\n", err)
	}

